const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number.isFinite(n)?n.toLocaleString('ko-KR',{maximumFractionDigits:2}):'—';
const pct=n=>Number.isFinite(n)?`${n>0?'+':''}${num(n)}%`:'—';
const time=(s,z='Asia/Seoul')=>s&&Number.isFinite(Date.parse(s))?new Intl.DateTimeFormat('ko-KR',{timeZone:z,dateStyle:'short',timeStyle:'short'}).format(new Date(s)):'시각 미확인';
const link=(u,t)=>/^https:\/\//.test(u||'')?`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(t)} ↗</a>`:esc(t);
const stages={quote:'Finviz 시세',search:'미국 원인 검색',read:'원문 수집',event:'AI 상승 재료 분석',discovery:'국내 기업 검색',business:'국내 사업 공시',transmission:'전달 근거 검증',complete:'완료'};
const states={queued:'수집 대기',running:'분석 중',ready:'근거 검증 완료',quote_failed:'시세 수집 실패',search_empty:'검색 결과 없음',body_unreadable:'원문 수집 실패',cause_unclear:'상승 원인 미확인',company_only:'기업 고유 사건',no_candidates:'관련 기업 없음',search_failed:'검색 실패',ai_failed:'AI 분석 실패',configuration_required:'검색·AI 연결 필요',business_unreadable:'국내 사업 공시 수집 실패',discovery_unreadable:'국내 검색 본문 수집 실패',processing_failed:'처리 실패',interrupted:'작업 중단',not_rising:'상승 종목 아님'};
export function mountObservations(root,{navigate}={}){
 let ticker='',seq=0,disposed=false,timer,searchTimer,searchAbort;
 root.innerHTML=`<div class="panel-heading"><div><h2>미국장 보고 찾은 국내 관찰 종목</h2><p class="us-kr-note">미국 종목 상승 → 확인된 상승 재료 → 국내 사업 근거</p></div></div><div class="us-kr-body observation-body"><form class="competitor-search"><label for="observation-search">미국 기업 찾기</label><div class="observation-search-line"><input id="observation-search" placeholder="기업명 검색 또는 미국 티커 입력" autocomplete="off"><button type="submit">분석 실행</button></div><div id="observation-search-results" aria-live="polite"></div></form><p class="us-kr-note">실제 원문을 확인하는 데 수 분 걸릴 수 있습니다. 동일 종목의 완료 결과는 6시간 재사용합니다.</p><div data-ob-result aria-live="polite"></div></div>`;
 const host=root.querySelector('[data-ob-result]'),input=root.querySelector('input'),matches=root.querySelector('#observation-search-results');
 function render(d){const r=d.selected,e=r?.event,q=r?.quote,s=r?.session;host.innerHTML=`${d.message?`<p role="status">${esc(d.message)}</p>`:''}${r?`<section class="observation-detail"><div class="observation-cause"><h3>${esc(q?.name||r.ticker)} · ${esc(r.ticker)} ${q?`<span>${pct(q.changePct)}</span>`:''}</h3><p><b>${esc(states[r.state]||r.state)}</b> · ${esc(stages[r.stage]||r.stage)}</p><p>${esc(r.message||'각 단계의 원문 근거를 확인하고 있습니다.')}</p>${q?`<p>정규장 종가 $${num(q.price)} · 미국 거래일 ${esc(s.sessionDate)} → 국내 ${esc(s.targetDate)}<br><small>미국 마감 ${time(s.closeAt,'America/New_York')} ET / ${time(s.closeAt)} KST · 수집 ${time(q.receivedAt)} KST</small></p>`:''}<ol class="observation-counts">${[['quote','시세'],['search','검색 결과'],['read','읽은 원문'],['event','검증된 재료'],['kr','국내 식별 후보'],['passed','근거 통과']].map(([k,l])=>`<li>${l} <b>${r.counts?.[k]||0}</b></li>`).join('')}</ol></div>
 <div class="observation-cause"><h3>확인된 상승 재료</h3>${e?.status==='verified'?`<p>${esc(e.event_summary)}</p><p>${esc(e.event_type)} · ${esc(e.affected_product_or_market.join(' · '))}</p><small>발표 ${time(e.published_at)} KST · 보도에 명시된 상승 배경이며 인과 확정은 아닙니다.</small>${e.evidence.map(x=>`<p>${link(x.url,'미국 근거 원문')}</p><blockquote>${esc(x.quote)}</blockquote>`).join('')}`:`<p>${r.state==='running'||r.state==='queued'?'원문 확인 중':'상승 원인 미확인'}</p>`}</div>
 <h3>국내 관찰 후보</h3><div class="us-kr-candidates">${(r.candidates||[]).map(c=>`<article class="us-kr-card observation-candidate"><h3><a href="/stock/KR/${esc(c.kr_ticker)}?tab=company">${esc(c.name)} · ${esc(c.kr_ticker)}</a></h3><p><span class="competitor-badge">${esc(c.relationship)}</span> · 방향 ${esc(c.transmission)} · 근거 신뢰도 ${esc(c.confidence)}</p><p><b>${esc(c.concrete_product)}</b><br>${esc(c.reason)}</p><p>${c.quote?`${num(c.quote.price)}원 · ${pct(c.quote.changePct)}<br><small>국내 일별 시세 ${esc(c.quote.baseDate)} · 수집 ${time(c.quote.syncedAt)} KST</small>`:'국내 시세 미확보'}</p><p>${link(c.event_evidence_url,'미국 재료')} · ${link(c.business_evidence_url,'DART 사업 근거')}</p><blockquote>${esc(c.business_quote)}</blockquote><small>공시 ${esc(c.business.sourceDate)} · 분석 ${time(c.analyzedAt)} KST</small></article>`).join('')||`<p class="us-kr-empty">${r.state==='running'||r.state==='queued'?'근거 검증 대기':esc(r.message)}<br><small>같은 섹터만으로 후보를 만들지 않습니다.</small></p>`}</div>
 ${r.coverage?`<p class="us-kr-note">국내 식별 ${r.coverage.discovered}개 / 사업 공시 확인 ${r.coverage.checked}개 · 실행당 최대 ${r.coverage.limit}개 확인. 미수집 기업의 부재를 뜻하지 않습니다.</p>`:''}
 <details class="observation-discovery"><summary>검색 원문·진단 기록</summary><p>분석 ${time(r.updatedAt||r.createdAt)} KST · ${esc(r.errorCode||'')} · ${esc(r.version||'')}</p>${(r.searches||[]).map(x=>`<h4>${esc(x.query)}</h4><ul>${x.items.map(i=>`<li>${link(i.url,i.title)}</li>`).join('')}</ul>`).join('')}${[...(r.sources||[]),...(r.discoverySources||[])].map(x=>`<p>${link(x.url,x.title)} · ${x.status==='read'?'본문 수집 완료':'본문 수집 실패 '+esc(x.code)} · 발행 ${time(x.publishedAt)} KST</p>`).join('')}<ul>${(r.excluded||[]).map(x=>`<li>${esc(x.name)} ${esc(x.ticker)} · ${esc(x.reason)}</li>`).join('')}</ul><ol>${(r.diagnostics||[]).map(x=>`<li>${esc(stages[x.stage])} · ${time(x.at)} KST · ${Object.values(x.counts||{}).join(' → ')}</li>`).join('')}</ol></details><p class="us-kr-note">미래 상승·매수 추천이 아닙니다. 시점 기준 과거 표본은 아직 검증되지 않아 표시하지 않습니다. 자동 상승주 배치는 단일 종목 실증 전까지 중지되어 있습니다.</p><button data-ob-retry>다시 분석</button></section>`:''}`;
 clearTimeout(timer);if(r&&['queued','running'].includes(r.state))timer=setTimeout(()=>load(ticker),3000);
 }
 async function load(t=ticker){const n=++seq;try{const response=await fetch('/api/us-observations'+(t?'?ticker='+encodeURIComponent(t):'')),d=await response.json();if(disposed||n!==seq)return;ticker=d.selected?.ticker||t;render(d);}catch{if(!disposed&&n===seq)host.textContent='분석 결과 조회 실패 · 새로고침해 주세요.';}}
 async function select(t){clearTimeout(timer);clearTimeout(searchTimer);searchAbort?.abort();const n=++seq;ticker=t;input.value=t;matches.innerHTML='';host.textContent='분석 요청 중…';try{const response=await fetch('/api/us-observations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ticker:t})}),d=await response.json();if(disposed||n!==seq)return;if(!response.ok){host.textContent=d.message||'분석 요청 실패';return;}render(d);}catch{if(!disposed&&n===seq)host.textContent='분석 요청 실패';}}
 root.querySelector('form').onsubmit=e=>{e.preventDefault();void select(input.value.trim().toUpperCase());};
 input.oninput=()=>{clearTimeout(searchTimer);searchAbort?.abort();const q=input.value.trim();matches.textContent='';if(!q)return;searchTimer=setTimeout(async()=>{const c=new AbortController();searchAbort=c;try{const d=await(await fetch('/api/us-observations?q='+encodeURIComponent(q),{signal:c.signal})).json();if(disposed||c.signal.aborted)return;matches.innerHTML=(d.items||[]).map(x=>`<button type="button" data-ob-select="${esc(x.ticker)}">${esc(x.ticker)} · ${esc(x.name)}</button>`).join('');}catch{}},250);};
 const click=e=>{const b=e.target.closest('button');if(b?.dataset.obSelect)void select(b.dataset.obSelect);if(b?.hasAttribute('data-ob-retry'))void select(ticker);const a=e.target.closest('a[href^="/"]');if(a&&navigate&&!e.ctrlKey&&!e.metaKey){e.preventDefault();navigate(a.getAttribute('href'));}};root.addEventListener('click',click);
 void load();return {refresh:()=>load(),destroy(){disposed=true;seq++;clearTimeout(timer);clearTimeout(searchTimer);searchAbort?.abort();root.removeEventListener('click',click);}};
}
